<?php

declare(strict_types=1);

namespace App\Application\Service;

use App\Domain\Entity\Subscriber;
use App\Domain\Port\Outbound\SubscriberRepositoryPort;
use InvalidArgumentException;

/**
 * Inbound Use Case Service generated by Tuzygent Hexagonal Harness
 */
final readonly class SubscriberService
{
    public function __construct(
        private SubscriberRepositoryPort $repository
    ) {
    }

    /**
     * @return Subscriber[]
     */
    public function listAll(): array
    {
        return $this->repository->findAll();
    }

    public function subscribe(string $email): bool
    {
        $email = strtolower(trim($email));
        if ($email === '' || strlen($email) > 254 || filter_var($email, FILTER_VALIDATE_EMAIL) === false) {
            throw new InvalidArgumentException('Vui lòng nhập địa chỉ email hợp lệ.');
        }

        if ($this->repository->findByEmail($email) !== null) {
            return false;
        }

        $this->repository->save(new Subscriber(
            id: null,
            email: $email,
            isActive: true,
            name: $email
        ));

        return true;
    }
}
